/* Reproduction: user cycled the attract loop to PREVIEW, pressed Space, and
 * landed in the BONUS interstitial instead of a fresh game.  Drives the exact
 * path and asserts GAME with a populated required-block grid. */
static void test_repro_space_from_preview(void **vstate)
{
    test_fixture_t *f = (test_fixture_t *)*vstate;
    game_ctx_t *ctx = f->ctx;

    sdl2_state_transition(ctx->state, SDL2ST_PREVIEW);
    for (int i = 0; i < 80; i++)
    {
        sdl2_input_begin_frame(ctx->input);
        sdl2_state_update(ctx->state);
    }

    sdl2_input_begin_frame(ctx->input);
    SDL_Event e = {0};
    e.type = SDL_KEYDOWN;
    e.key.keysym.scancode = SDL_SCANCODE_SPACE;
    sdl2_input_process_event(ctx->input, &e);
    game_input_global(ctx);

    fprintf(stderr, "[repro] after space: mode=%d still_active=%d\n",
            (int)sdl2_state_current(ctx->state), block_system_still_active(ctx->block));

    for (int i = 0; i < 10; i++)
    {
        sdl2_input_begin_frame(ctx->input);
        sdl2_state_update(ctx->state);
    }
    fprintf(stderr, "[repro] after 10 game ticks: mode=%d (BONUS=%d GAME=%d)\n",
            (int)sdl2_state_current(ctx->state), SDL2ST_BONUS, SDL2ST_GAME);

    assert_int_equal(sdl2_state_current(ctx->state), SDL2ST_GAME);
}

