static void highscore_cb_on_finished(highscore_type_t type, void *ud)
{
    (void)type;
    game_ctx_t *ctx = ud;
    /* Clear the game-over flag before returning to the attract cycle.  A
     * game-over Highscore display keeps game_active true (it gates score
     * submission); when the finish-timer auto-advances to the next attract
     * screen the session is over, so game_active must be cleared — the
     * Space handler (game_input.c:415) does the same on its exit.  Without
     * this the flag leaks into the attract screens and the next Highscore's
     * Space returns to Intro instead of starting a game (ADR-055). */
    ctx->game_active = false;
    /* Sound (gate@50, original/highscore.c:492) is stored in
     * highscore_system's sound struct and relayed by
     * mode_highscore_update — matches the keys/presents/intro/etc.
     * relay pattern.  Callback only handles the state transition. */
    sdl2_state_transition(ctx->state, game_callbacks_attract_next(SDL2ST_HIGHSCORE));
}

