/*
 * harness.c — scratch, one-off proof that editor_cb_save_level's line-2
 * time-bonus write matches the level's real bonus (fixed) vs. is always
 * "120" (buggy).  Not part of the tracked test suite; not linked via
 * CMakeLists.  See mission m-2026-07-12-001 report for context.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "block_system.h"
#include "editor_system.h"
#include "game_callbacks.h"
#include "game_context.h"
#include "level_system.h"

int main(void)
{
    /* Write a scratch level file with a known, non-120 time bonus. */
    const char *level_path = "/tmp/verify_time_bonus_level.dat";
    FILE *lf = fopen(level_path, "w");
    if (!lf)
    {
        fprintf(stderr, "cannot create scratch level file\n");
        return 1;
    }
    fprintf(lf, "Verify Level\n");
    fprintf(lf, "60\n");
    for (int r = 0; r < LEVEL_GRID_ROWS; r++)
    {
        for (int c = 0; c < LEVEL_GRID_COLS; c++)
            fputc('.', lf);
        fputc('\n', lf);
    }
    fclose(lf);

    level_system_status_t lstatus;
    level_system_t *level = level_system_create(NULL, NULL, &lstatus);
    if (!level || lstatus != LEVEL_SYS_OK)
    {
        fprintf(stderr, "level_system_create failed\n");
        return 1;
    }
    if (level_system_load_file(level, level_path) != LEVEL_SYS_OK)
    {
        fprintf(stderr, "level_system_load_file failed\n");
        return 1;
    }
    int real_bonus = level_system_get_time_bonus(level);
    printf("real bonus loaded into level_system: %d\n", real_bonus);

    editor_system_t *editor = editor_system_create(NULL, NULL, "/tmp", "/tmp", 1);
    if (!editor)
    {
        fprintf(stderr, "editor_system_create failed\n");
        return 1;
    }

    block_system_status_t bstatus;
    block_system_t *block = block_system_create(55, 32, &bstatus);
    if (!block || bstatus != BLOCK_SYS_OK)
    {
        fprintf(stderr, "block_system_create failed\n");
        return 1;
    }

    game_ctx_t *ctx = calloc(1, sizeof(*ctx));
    if (!ctx)
    {
        fprintf(stderr, "calloc failed\n");
        return 1;
    }
    ctx->level = level;
    ctx->editor = editor;
    ctx->block = block;

    editor_system_callbacks_t cbs = game_callbacks_editor();
    const char *save_path = "/tmp/verify_time_bonus_saved.dat";
    int ok = cbs.on_save_level(save_path, ctx);
    if (!ok)
    {
        fprintf(stderr, "on_save_level returned failure\n");
        return 1;
    }

    FILE *sf = fopen(save_path, "r");
    if (!sf)
    {
        fprintf(stderr, "cannot reopen saved file\n");
        return 1;
    }
    char line1[256];
    char line2[256];
    if (!fgets(line1, sizeof(line1), sf) || !fgets(line2, sizeof(line2), sf))
    {
        fprintf(stderr, "cannot read back saved lines\n");
        return 1;
    }
    fclose(sf);

    /* Strip trailing newline for clean comparison/printing */
    line2[strcspn(line2, "\n")] = '\0';

    printf("line 2 of saved file: '%s'\n", line2);

    int written = atoi(line2);
    if (written != real_bonus)
    {
        printf("MISMATCH: wrote %d, real bonus is %d\n", written, real_bonus);
        return 2;
    }

    printf("MATCH: saved file line 2 (%d) equals real bonus (%d)\n", written, real_bonus);
    return 0;
}

