/* =========================================================================
 * Section 5: Editor save-path time bonus (bead xboing-di8)
 *
 * editor_cb_save_level() in src/game_callbacks.c is static and pulls in the
 * full game_ctx_t / SDL2 subsystem graph, so it cannot be linked into this
 * lightweight executable (linked against level_system only -- see
 * tests/CMakeLists.txt).  This mirrors its line-2 write exactly -- the same
 * expression, `level_system_get_time_bonus(level)` -- against a REAL level
 * file's bonus (not a synthetic value), so a regression back to a hardcoded
 * constant on either side shows up as a mismatch against a value the
 * hardcoded bug could never produce.
 *
 * Prior to this fix, editor_cb_save_level wrote a hardcoded "120\n" for
 * every save regardless of the level's actual time bonus, corrupting
 * levels whose real bonus differs (74/80 level files use a value other
 * than 120; level02.data uses 150).
 * ========================================================================= */

static int write_editor_style_save(const char *path, const char *title,
                                   const level_system_t *level,
                                   int grid[LEVEL_GRID_ROWS][LEVEL_GRID_COLS])
{
    FILE *fp = fopen(path, "w");
    if (!fp)
        return 0;

    fprintf(fp, "%s\n", title);
    fprintf(fp, "%d\n", level_system_get_time_bonus(level));

    for (int row = 0; row < LEVEL_GRID_ROWS; row++)
    {
        for (int col = 0; col < LEVEL_GRID_COLS; col++)
            fputc(test_block_type_to_char(grid[row][col]), fp);
        fputc('\n', fp);
    }

    fclose(fp);
    return 1;
}

static void test_save_time_bonus_matches_real_level_not_hardcoded_120(void **vstate)
{
    test_fixture_t *f = (test_fixture_t *)*vstate;

    /* Load a real level file whose bonus is NOT 120 (level02.data == 150). */
    const char *level_path = LEVELS_DIR "/level02.data";
    level_system_status_t status = level_system_load_file(f->level, level_path);
    if (status == LEVEL_SYS_ERR_FILE_NOT_FOUND)
    {
        skip();
        return;
    }
    assert_int_equal(status, LEVEL_SYS_OK);
    assert_int_equal(level_system_get_time_bonus(f->level), 150);

    /* Save it out through the same expression the editor save path uses. */
    char save_path[256];
    snprintf(save_path, sizeof(save_path), "/tmp/test_editor_rt_save_XXXXXX");
    int fd = mkstemp(save_path);
    assert_true(fd >= 0);
    close(fd);

    int grid[LEVEL_GRID_ROWS][LEVEL_GRID_COLS];
    for (int r = 0; r < LEVEL_GRID_ROWS; r++)
        for (int c = 0; c < LEVEL_GRID_COLS; c++)
            grid[r][c] = NONE_BLK;

    assert_true(write_editor_style_save(save_path, level_system_get_title(f->level), f->level, grid));

    /* Read back line 2 and confirm it matches the real bonus, not the
     * value the pre-fix hardcoded literal would have written. */
    FILE *fp = fopen(save_path, "r");
    assert_non_null(fp);
    char line1[256];
    char line2[256];
    assert_non_null(fgets(line1, sizeof(line1), fp));
    assert_non_null(fgets(line2, sizeof(line2), fp));
    fclose(fp);
    unlink(save_path);

    line2[strcspn(line2, "\n")] = '\0';
    int written_bonus = (int)strtol(line2, NULL, 10);

    assert_int_equal(written_bonus, 150);
    assert_int_equal(written_bonus, level_system_get_time_bonus(f->level));
    assert_int_not_equal(written_bonus, 120);
}

/* =========================================================================
 * Test runner
 * ========================================================================= */

    /* Section 4: Real level file */
    cmocka_unit_test_setup_teardown(test_load_real_level01, setup, teardown),

    /* Section 5: Editor save-path time bonus (bead xboing-di8) */
    cmocka_unit_test_setup_teardown(test_save_time_bonus_matches_real_level_not_hardcoded_120,
                                    setup, teardown),
};

