 * Test runner
 * ========================================================================= */

    cmocka_unit_test_setup_teardown(test_editor_save_writes_real_time_bonus, setup_edit_save,
                                    teardown_edit_save),
    cmocka_unit_test_setup_teardown(test_editor_save_preserves_counter_and_random,
                                    setup_edit_save, teardown_edit_save),
};

