/* Throwaway harness — jdc, m-2026-07-15-003.  Not part of write_set;
 * deleted after verification. */
#include <stdio.h>

#include "block_system.h"
#include "block_types.h"

int main(void)
{
    block_system_status_t status;
    block_system_t *ctx = block_system_create(55, 32, &status);
    if (!ctx)
    {
        printf("create failed\n");
        return 1;
    }

    /* Scenario A: free roamer at (5,4), plenty of open cells around it,
     * no balls in play.  Force bonus_slide=4 (Down) and fire the move
     * timer this frame -- it must relocate to (6,4) and clear (5,4). */
    int frame = 1000;
    block_system_add(ctx, 5, 4, ROAMER_BLK, 0, frame);
    block_system_set_last_frame(ctx, 5, 4, frame); /* not exposed for bonus_slide -- use internal via re-add trick below */

    /* We can't set bonus_slide directly (no public setter -- by design,
     * it's internal movement state).  Instead run many ticks with a
     * fixed seed and observe over time that a roamer in open space moves
     * at least once within a generous tick budget, and a boxed-in roamer
     * never does. */
    block_system_destroy(ctx);

    /* Real scenario: run 5000 ticks, srand(1), open roamer must move. */
    ctx = block_system_create(55, 32, &status);
    block_system_add(ctx, 5, 4, ROAMER_BLK, 0, 0);
    int moved = 0;
    int last_r = 5, last_c = 4;
    for (int f = 0; f < 5000 && !moved; f++)
    {
        block_system_update_movement(ctx, f, NULL, 0);
        for (int r = 0; r < MAX_ROW && !moved; r++)
        {
            for (int c = 0; c < MAX_COL && !moved; c++)
            {
                if (block_system_get_type(ctx, r, c) == ROAMER_BLK && (r != last_r || c != last_c))
                {
                    printf("Scenario open: roamer moved from (%d,%d) to (%d,%d) at frame %d\n",
                          last_r, last_c, r, c, f);
                    moved = 1;
                }
            }
        }
    }
    if (!moved)
        printf("Scenario open: FAIL -- roamer never moved in 5000 ticks\n");
    block_system_destroy(ctx);

    /* Boxed scenario: surround (5,4) on all four sides with occupied
     * blocks, and place it far enough from the bottom that only the
     * adjacency-occupancy gate is exercised.  It must never move. */
    ctx = block_system_create(55, 32, &status);
    block_system_add(ctx, 5, 4, ROAMER_BLK, 0, 0);
    block_system_add(ctx, 4, 4, RED_BLK, 0, 0); /* up */
    block_system_add(ctx, 6, 4, RED_BLK, 0, 0); /* down */
    block_system_add(ctx, 5, 3, RED_BLK, 0, 0); /* left */
    block_system_add(ctx, 5, 5, RED_BLK, 0, 0); /* right */
    int boxed_moved = 0;
    for (int f = 0; f < 5000; f++)
    {
        block_system_update_movement(ctx, f, NULL, 0);
        if (block_system_get_type(ctx, 5, 4) != ROAMER_BLK)
