/*
 * verify_debug_skip.c -- scratch verification harness (not a committed
 * test). Confirms:
 *   1. Shift+'=' triggers volume up.
 *   2. Unshifted '=' in SDL2ST_GAME with debug_mode=false shows
 *      "Stop trying to cheat!!" and does not clear blocks.
 *   3. Unshifted '=' in SDL2ST_GAME with debug_mode=true clears the
 *      required blocks (block_system_still_active -> 0) and shows
 *      "Cheating, skip level ...".
 *   4. Numpad '+' still triggers volume up.
 */

#include <stdio.h>
#include <string.h>

#include <SDL2/SDL.h>

#include "block_system.h"
#include "game_context.h"
#include "game_init.h"
#include "game_input.h"
#include "message_system.h"
#include "sdl2_audio.h"
#include "sdl2_input.h"
#include "sdl2_state.h"

static char arg_prog[] = "xboing_verify";

static void inject_key_mod(game_ctx_t *ctx, SDL_Scancode sc, SDL_Keymod mod)
{
    sdl2_input_begin_frame(ctx->input);
    SDL_Event e = {0};
    e.type = SDL_KEYDOWN;
    e.key.keysym.scancode = sc;
    e.key.keysym.mod = mod;
    e.key.repeat = 0;
    sdl2_input_process_event(ctx->input, &e);
}

static int failures = 0;

#define CHECK(cond, msg)                                                                         \
    do                                                                                            \
    {                                                                                             \
        if (cond)                                                                                 \
            printf("PASS: %s\n", msg);                                                            \
        else                                                                                       \
        {                                                                                          \
            printf("FAIL: %s\n", msg);                                                            \
            failures++;                                                                            \
        }                                                                                          \
    } while (0)

static game_ctx_t *make_game_ctx(void)
{
    char *argv[] = {arg_prog, NULL};
    game_ctx_t *ctx = game_create(1, argv);
    ctx->config.use_keys = true;
    sdl2_state_transition(ctx->state, SDL2ST_PRESENTS);
    sdl2_state_transition(ctx->state, SDL2ST_GAME);
    return ctx;
}

int main(void)
{
    setenv("SDL_VIDEODRIVER", "dummy", 1);
    setenv("SDL_AUDIODRIVER", "dummy", 1);

    /* --- Test 1: Shift+'=' -> volume up --- */
    {
        game_ctx_t *ctx = make_game_ctx();
        int before = ctx->audio ? sdl2_audio_get_volume(ctx->audio) : -1;
        inject_key_mod(ctx, SDL_SCANCODE_EQUALS, KMOD_LSHIFT);
        game_input_global(ctx);
        int after = ctx->audio ? sdl2_audio_get_volume(ctx->audio) : -1;
        CHECK(before >= 0 && after == before + 1, "Shift+'=' increments volume");
        game_destroy(ctx);
    }

    /* --- Test 2: unshifted '=' without debug_mode --- */
    {
        game_ctx_t *ctx = make_game_ctx();
        ctx->debug_mode = false;
        /* Occupy one required cell so we can prove it's untouched. */
        block_system_add(ctx->block, 0, 0, RED_BLK, 0, 0);
        inject_key_mod(ctx, SDL_SCANCODE_EQUALS, KMOD_NONE);
        game_input_global(ctx);
        CHECK(block_system_is_occupied(ctx->block, 0, 0), "no-debug '=' leaves blocks untouched");
        CHECK(strcmp(message_system_get_text(ctx->message), "Stop trying to cheat!!") == 0,
              "no-debug '=' shows 'Stop trying to cheat!!'");
        game_destroy(ctx);
    }

    /* --- Test 3: unshifted '=' with debug_mode --- */
    {
        game_ctx_t *ctx = make_game_ctx();
        ctx->debug_mode = true;
        block_system_add(ctx->block, 0, 0, RED_BLK, 0, 0);
        block_system_add(ctx->block, 1, 0, BLACK_BLK, 0, 0); /* special: must survive */
        CHECK(block_system_still_active(ctx->block) != 0, "grid starts with required block");
        inject_key_mod(ctx, SDL_SCANCODE_EQUALS, KMOD_NONE);
        game_input_global(ctx);
        CHECK(block_system_still_active(ctx->block) == 0,
              "debug '=' clears required blocks (still_active -> 0)");
        CHECK(block_system_is_occupied(ctx->block, 1, 0), "debug '=' leaves BLACK_BLK special intact");
        CHECK(strcmp(message_system_get_text(ctx->message), "Cheating, skip level ...") == 0,
              "debug '=' shows 'Cheating, skip level ...'");
        game_destroy(ctx);
    }

    /* --- Test 4: numpad '+' still volume up --- */
    {
        game_ctx_t *ctx = make_game_ctx();
        int before = ctx->audio ? sdl2_audio_get_volume(ctx->audio) : -1;
        inject_key_mod(ctx, SDL_SCANCODE_KP_PLUS, KMOD_NONE);
        game_input_global(ctx);
        int after = ctx->audio ? sdl2_audio_get_volume(ctx->audio) : -1;
        CHECK(before >= 0 && after == before + 1, "numpad '+' increments volume");
        game_destroy(ctx);
    }

    if (failures == 0)
        printf("\nALL CHECKS PASSED\n");
    else
        printf("\n%d CHECK(S) FAILED\n", failures);

    return failures == 0 ? 0 : 1;
}

