/*
 * Throwaway runtime harness -- round 2 verification of the '=' debug
 * skip-level cheat.  Not part of the test suite; not registered in
 * CMakeLists.txt.  Compiled and run ad hoc, then discarded.
 */
#include <stdio.h>
#include <stdlib.h>

#include <SDL2/SDL.h>

#include "block_system.h"
#include "game_callbacks.h"
#include "game_context.h"
#include "game_init.h"
#include "game_input.h"
#include "score_system.h"
#include "sdl2_input.h"
#include "sdl2_state.h"
#include "sfx_system.h"
#include "special_system.h"

static void inject_key(game_ctx_t *ctx, SDL_Scancode sc, int shift)
{
    sdl2_input_begin_frame(ctx->input);
    SDL_Event e = {0};
    e.type = SDL_KEYDOWN;
    e.key.keysym.scancode = sc;
    e.key.keysym.mod = shift ? KMOD_LSHIFT : KMOD_NONE;
    e.key.repeat = 0;
    sdl2_input_process_event(ctx->input, &e);
}

static int count_required_occupied(game_ctx_t *ctx)
{
    int n = 0;
    for (int r = 0; r < MAX_ROW; r++)
    {
        for (int c = 0; c < MAX_COL; c++)
        {
            if (!block_system_is_occupied(ctx->block, r, c))
                continue;
            switch (block_system_get_type(ctx->block, r, c))
            {
                case RED_BLK:
                case BLUE_BLK:
                case GREEN_BLK:
                case TAN_BLK:
                case YELLOW_BLK:
                case PURPLE_BLK:
                case COUNTER_BLK:
                case DROP_BLK:
                    n++;
                    break;
                default:
                    break;
            }
        }
    }
    return n;
}

int main(void)
{
    char arg0[] = "xboing_test";
    char arg1[] = "-debug";
    char *argv[] = {arg0, arg1, NULL};
    game_ctx_t *ctx = game_create(2, argv);
    if (!ctx)
    {
        fprintf(stderr, "game_create failed\n");
        return 1;
    }
    printf("debug_mode = %d\n", ctx->debug_mode);

    ctx->config.use_keys = true;
    sdl2_state_transition(ctx->state, SDL2ST_PRESENTS);
    sdl2_state_transition(ctx->state, SDL2ST_GAME);

    int required_before = count_required_occupied(ctx);
    int still_active_before = block_system_still_active(ctx->block);
    unsigned long score_before = score_system_get(ctx->score);
    int x2_before = special_system_is_active(ctx->special, SPECIAL_X2_BONUS);
    int x4_before = special_system_is_active(ctx->special, SPECIAL_X4_BONUS);

    printf("required blocks before: %d, still_active: %d, score: %lu, x2=%d x4=%d\n",
           required_before, still_active_before, score_before, x2_before, x4_before);

    /* Fire the cheat: unshifted '=' in GAME mode. */
    inject_key(ctx, SDL_SCANCODE_EQUALS, 0);
    game_input_global(ctx);

    int required_immediately_after = count_required_occupied(ctx);
    sfx_mode_t sfx_mode = sfx_system_get_mode(ctx->sfx);
    unsigned long score_immediately_after = score_system_get(ctx->score);

    printf("required blocks immediately after explode call: %d (occupied cleared already, "
           "exploding in flight)\n",
           required_immediately_after);
    printf("sfx mode immediately after: %d (SFX_MODE_SHAKE=%d)\n", sfx_mode, SFX_MODE_SHAKE);
    printf("score immediately after (should be UNCHANGED -- deferred to finalize): %lu\n",
           score_immediately_after);

    /* Advance frames until all explosions finalize (~40 ticks per the
     * BLOCK_EXPLODE_DELAY stage cadence) and block_system_still_active
     * drops to 0. */
    int frame = (int)sdl2_state_frame(ctx->state);
    for (int i = 0; i < 200; i++)
    {
        frame++;
        block_system_update_explosions(ctx->block, frame, game_callbacks_on_block_finalize, ctx);
        if (block_system_still_active(ctx->block) == 0)
        {
            printf("still_active reached 0 after %d finalize ticks\n", i + 1);
            break;
        }
    }

    unsigned long score_after = score_system_get(ctx->score);
    int still_active_after = block_system_still_active(ctx->block);

    printf("final score: %lu (delta = %lu)\n", score_after, score_after - score_before);
    printf("still_active after finalize loop: %d\n", still_active_after);
    printf("x2=%d x4=%d specials preserved\n", special_system_is_active(ctx->special, SPECIAL_X2_BONUS),
           special_system_is_active(ctx->special, SPECIAL_X4_BONUS));

    game_destroy(ctx);
    return 0;
}

