static int g_warn_count = 0;

static void log_fn(void *userdata, int category, SDL_LogPriority priority, const char *message)
{
    (void)userdata;
    (void)category;
    if (priority >= SDL_LOG_PRIORITY_WARN && strstr(message, "no free channel") != NULL)
    {
        g_warn_count++;
        fprintf(stderr, "CAUGHT WARN: %s\n", message);
    }
}

int main(void)
{
    setenv("SDL_VIDEODRIVER", "dummy", 1);
    setenv("SDL_AUDIODRIVER", "dummy", 1);

    SDL_LogSetOutputFunction(log_fn, NULL);

    char prog[] = "xboing";
    char *argv[] = {prog, NULL};
    game_ctx_t *ctx = game_create(1, argv);
    if (!ctx)
    {
        fprintf(stderr, "game_create failed\n");
        return 1;
    }
    ctx->config.use_keys = true;
    ctx->debug_mode = true;

    sdl2_state_transition(ctx->state, SDL2ST_PRESENTS);
    sdl2_state_transition(ctx->state, SDL2ST_GAME);

    int required = 0;
    for (int row = 0; row < MAX_ROW; row++)
        for (int col = 0; col < MAX_COL; col++)
            if (block_system_is_occupied(ctx->block, row, col))
            {
                int t = block_system_get_type(ctx->block, row, col);
                switch (t)
                {
                    case RED_BLK:
                    case BLUE_BLK:
