/* Throwaway verification harness for m-2026-07-17-001 (ADR-073).
 * Not part of the committed test suite -- mirrors ADR-072's ad hoc
 * throwaway harness precedent. Deleted after use. */
#include <stdio.h>
#include <string.h>

#include <SDL2/SDL.h>

#include "game_context.h"
#include "game_init.h"
#include "game_input.h"
#include "sdl2_input.h"
#include "sdl2_state.h"

static void inject_key(game_ctx_t *ctx, SDL_Scancode sc)
{
    sdl2_input_begin_frame(ctx->input);
    SDL_Event e = {0};
    e.type = SDL_KEYDOWN;
    e.key.keysym.scancode = sc;
    e.key.repeat = 0;
    sdl2_input_process_event(ctx->input, &e);
}

static int failures = 0;

static void check(const char *label, int cond)
{
    printf("%s: %s\n", cond ? "PASS" : "FAIL", label);
    if (!cond)
        failures++;
}

int main(void)
{
    char prog[] = "xboing_verify";
    char *argv[] = {prog, NULL};
    game_ctx_t *ctx = game_create(1, argv);
    check("game_create succeeded", ctx != NULL);

    ctx->config.use_keys = true;
    sdl2_state_transition(ctx->state, SDL2ST_PRESENTS);
    sdl2_state_transition(ctx->state, SDL2ST_GAME);

    check("cheated starts false after start_new_game", ctx->cheated == false);

    /* Not in debug mode: '=' should NOT set cheated (the "Stop trying to
     * cheat!!" no-op path). */
    ctx->debug_mode = false;
    inject_key(ctx, SDL_SCANCODE_EQUALS);
    game_input_global(ctx);
    check("cheated stays false on '=' without -debug", ctx->cheated == false);

    /* Debug mode on: '=' explodes blocks and must set cheated. */
    ctx->debug_mode = true;
    inject_key(ctx, SDL_SCANCODE_EQUALS);
    game_input_global(ctx);
    check("cheated becomes true after '=' cheat with -debug", ctx->cheated == true);

    /* Starting a fresh game must reset the flag. */
    sdl2_state_transition(ctx->state, SDL2ST_PRESENTS);
    sdl2_state_transition(ctx->state, SDL2ST_INTRO);
    sdl2_state_transition(ctx->state, SDL2ST_GAME);
    check("cheated resets false on next start_new_game", ctx->cheated == false);

    game_destroy(ctx);

    printf("%s\n", failures == 0 ? "ALL CHECKS PASSED" : "SOME CHECKS FAILED");
    return failures == 0 ? 0 : 1;
}

