 * ========================================================================= */

bool dialogue_key_from_sdl(SDL_Keycode sym, dialogue_key_type_t *out)
{
    if (out == NULL)
        return false;

    switch (sym)
    {
        case SDLK_RETURN:
            *out = DIALOGUE_KEY_RETURN;
            return true;

        /* original/dialogue.c:327-328 aliases XK_Delete to XK_BackSpace. */
        case SDLK_DELETE:
        case SDLK_BACKSPACE:
            *out = DIALOGUE_KEY_BACKSPACE;
            return true;

        case SDLK_ESCAPE:
            *out = DIALOGUE_KEY_ESCAPE;
            return true;

        default:
            return false;
    }
}

